# Chaque article comporte une réponse ciblée, des sections réellement distinctes, des Q/R et des renvois éditoriaux.
ARTICLES=[
 dict(slug='wyylde-avis',cluster='Enquête & avis',title='Wyylde avis 2026 : faut-il vraiment payer ?',desc='Avis indépendant sur Wyylde : prix officiel, profils, expérience, limites et questions à poser avant de s’abonner.',question='Wyylde vaut-il le coup en 2026 ?',answer='Wyylde peut intéresser les adultes recherchant une communauté libertine francophone, mais l’inscription gratuite ne donne pas accès à toutes les interactions. L’abonnement Gold coûte officiellement 22,90 € pour un mois, 44,90 € pour trois mois ou 99,90 € pour un an. Vérifiez l’activité locale et le renouvellement avant de payer.',sections=[('Notre verdict, sans fausse expérience','Wyylde se présente comme un réseau social réservé aux personnes majeures, combinant profils, échanges et contenus communautaires. Il s’adresse davantage aux personnes qui souhaitent prendre le temps de découvrir une communauté qu’à celles qui veulent des résultats garantis. Cet avis repose sur la documentation officielle et des retours publics, et non sur un compte d’essai prétendument utilisé par notre rédaction.','Le point essentiel : payer débloque des interactions, mais n’achète ni rencontre, ni réponse, ni vérification absolue de l’identité des membres.'),('Les points positifs à considérer','L’existence d’un compte de couple et des fonctionnalités d’échange variées peut faciliter l’exploration des affinités. L’ancienneté du service et l’existence d’une documentation d’aide détaillée sont des éléments utiles pour comparer. La taille globale revendiquée d’une communauté ne renseigne cependant pas sur le nombre de profils actifs autour de vous.'),('Les limites à connaître','Le coût est réel, l’abonnement se renouvelle par défaut et les expériences varient selon la ville, le profil et les attentes. Les avis publics font apparaître des critiques sur les faux profils présumés, le rapport qualité-prix et l’évolution du service. Ce sont des témoignages subjectifs, non des mesures vérifiées de la proportion de faux comptes.'),('Décider sans se précipiter','Avant paiement, créez un profil sobre, observez les rubriques disponibles gratuitement, étudiez les conditions en vigueur et vérifiez les moyens d’arrêter le renouvellement. Comparez ensuite avec deux alternatives sur les mêmes critères. Une formule mensuelle peut limiter votre engagement financier si vous souhaitez d’abord évaluer l’utilité réelle du service.')],faq=[('Wyylde est-il fiable ?','Wyylde est un service identifié avec des conditions d’utilisation officielles ; cela ne signifie pas que tous les profils ou échanges soient fiables. Évaluez séparément la sécurité de la plateforme et le comportement de chaque contact.'),('Peut-on rencontrer quelqu’un gratuitement ?','L’inscription est gratuite, mais les interactions centrales nécessitent généralement Gold. Il faut examiner la liste exacte des fonctions accessibles avant tout paiement.'),('Quel est le tarif de Wyylde ?','Les prix publiés par le centre d’aide en avril 2026 sont 22,90 € le mois, 44,90 € le trimestre et 99,90 € l’année, réglés d’avance pour les deux durées longues.')],sources=['tarifs','cgu','avis','resiliation']),
 dict(slug='wyylde-prix',cluster='Prix & abonnement',title='Prix Wyylde 2026 : les vrais tarifs Gold',desc='Tarifs Wyylde Gold sourcés : 1 mois, 3 mois, 12 mois, coût total et renouvellement automatique.',question='Combien coûte Wyylde en 2026 ?',answer='Selon le centre d’aide officiel Wyylde mis à jour le 15 avril 2026, Gold coûte 22,90 € pour un mois, 44,90 € pour trois mois et 99,90 € pour un an en France. Les forfaits trimestriel et annuel sont payés en une fois ; les montants peuvent varier selon le pays ou de nouvelles offres.',sections=[('Comparer le montant réellement débité','Le prix au mois parfois affiché pour les formules longues est un calcul comparatif, pas un étalement du paiement. Vous êtes débité de la période souscrite en une fois. Le trimestre représente environ 14,97 € par mois ; l’année, environ 8,33 € par mois. Cette différence peut être significative mais elle n’est intéressante que si le service vous convient durablement.'),('Gold : les fonctions concernées','Le centre d’aide explique que Gold permet d’utiliser les fonctionnalités illimitées et que tous les statuts de compte sont soumis au même principe. Les CGU mentionnent les interactions, la messagerie, les commentaires et certains médias parmi les usages couverts par l’offre payante. Faites la différence entre consulter un profil restreint et interagir effectivement.'),('Attention au renouvellement automatique','Le renouvellement est activé par défaut lors de la souscription selon l’aide officielle. Il peut être désactivé depuis Paramètres → Abonnement. Le délai précisé par l’aide est d’au moins 24 heures avant le renouvellement ; évitez d’effectuer l’opération au dernier moment.'),('Comment choisir','Pour une première découverte, le coût total et le degré d’incertitude doivent guider la décision. Évitez d’acheter douze mois seulement parce que le prix ramené au mois semble attractif. Conservez une copie des conditions et du reçu de paiement, puis vérifiez que la date de fin est bien comprise.')],faq=[('Wyylde est-il gratuit pour les femmes ?','Non : l’aide officielle précise qu’aucun tarif préférentiel n’est accordé aux femmes ou aux couples pour Gold.'),('Peut-on payer 99,90 € en douze fois ?','Non : la formule annuelle est réglée en une seule fois, même lorsque son équivalent mensuel est mis en avant.'),('Existe-t-il une offre de parrainage ?','Le centre d’aide décrit un mois offert aux deux personnes lorsque les conditions du parrainage sont intégralement remplies, notamment la souscription initiale à Gold.')],sources=['tarifs','resiliation','parrainage']),
 dict(slug='wyylde-gratuit',cluster='Prix & abonnement',title='Wyylde gratuit : que peut-on faire sans payer ?',desc='Inscription gratuite, accès restreint, messages et Gold : les fonctionnalités gratuites et payantes de Wyylde.',question='Wyylde est-il vraiment gratuit ?',answer='L’inscription à Wyylde est gratuite et permet notamment de créer un profil et de consulter certaines pages ou profils en mode restreint. En revanche, la messagerie, les échanges et plusieurs contenus nécessitent l’abonnement Gold selon les conditions officielles du service.',sections=[('Ce que signifie « gratuit »','Une inscription sans frais n’équivaut pas à un accès illimité. Les CGU distinguent les services ouverts après inscription des services Gold. Avant de saisir vos coordonnées de paiement, identifiez les fonctions que vous souhaitez vraiment utiliser et leurs éventuelles restrictions.'),('Créer un compte sans mauvaise surprise','Commencez par renseigner un pseudonyme non identifiable et parcourir les éléments accessibles sans paiement. Ne partez pas du principe que tous les profils, médias et discussions seront accessibles. Une page de présentation peut être visible alors que l’interaction avec son auteur ne l’est pas.'),('Le piège des comparatifs périmés','Des pages non mises à jour promettent parfois la gratuité permanente selon le sexe ou un ancien statut. L’aide officielle précise au contraire que tous les statuts doivent payer Gold pour les fonctions payantes. Les offres promotionnelles et conditions peuvent évoluer.'),('Notre méthode d’évaluation','Avant de souscrire, notez les critères suivants : activité locale pertinente, qualité des profils visibles, outils de confidentialité et coût total. Si vous ne voyez aucun élément convaincant, un abonnement n’améliorera pas nécessairement l’expérience.')],faq=[('Wyylde est-il gratuit pour les couples ?','L’inscription l’est, mais Gold est payant pour les couples comme pour les autres statuts.'),('Peut-on envoyer des messages sans Gold ?','Les CGU présentent la messagerie et les interactions parmi les fonctionnalités de l’abonnement Gold.'),('Wyylde propose-t-il un essai gratuit ?','Aucune période d’essai gratuite universelle n’est confirmée dans les sources officielles citées ici. Vérifiez les offres disponibles depuis le service.')],sources=['cgu','tarifs']),
 dict(slug='wyylde-resiliation',cluster='Prix & abonnement',title='Résilier Wyylde : arrêter le renouvellement Gold',desc='Comment résilier Wyylde : chemin exact dans les paramètres, délai officiel, fin d’accès et preuve de désactivation.',question='Comment arrêter son abonnement Wyylde ?',answer='Selon le centre d’aide Wyylde, ouvrez Paramètres, puis Abonnement et cliquez sur « désactiver » pour arrêter le renouvellement automatique. Effectuez cette démarche au moins 24 heures avant l’échéance. L’abonnement déjà payé reste normalement actif jusqu’à la fin de la période.',sections=[('La procédure officielle','Connectez-vous à votre compte et ouvrez les paramètres. Dans la rubrique Abonnement, désactivez l’option de renouvellement puis finalisez le formulaire de confirmation. Assurez-vous qu’une date de fin d’abonnement ou une confirmation claire est affichée. Prenez une capture pour vos archives personnelles, sans la publier.'),('Résiliation et suppression ne sont pas identiques','Arrêter le renouvellement empêche un nouveau paiement automatique, mais ne supprime pas le compte. Effacer le compte est une autre opération disponible dans les paramètres de sécurité. Le centre d’aide indique qu’une suppression entraîne aussi l’arrêt du renouvellement ; elle ne suspend pas l’abonnement déjà en cours.'),('Que faire en cas de difficulté','Si le bouton est absent ou si une facturation semble incorrecte, contactez l’assistance par les canaux officiels en joignant les références de paiement pertinentes, sans transmettre publiquement les détails de carte. Gardez les dates et les preuves écrites des demandes effectuées.'),('Éviter une nouvelle reconduction','Consultez le détail du contrat avant souscription puis définissez un rappel personnel avant l’échéance. La règle officielle mentionne au moins 24 heures, mais se ménager une marge de plusieurs jours est plus prudent.')],faq=[('La résiliation de Wyylde est-elle immédiate ?','La désactivation du renouvellement prend effet pour la prochaine échéance ; la période déjà payée reste normalement accessible jusqu’à son terme.'),('Peut-on résilier Wyylde depuis son mobile ?','Si les paramètres d’abonnement sont accessibles depuis le navigateur mobile, suivez la même rubrique Paramètres → Abonnement et vérifiez la confirmation.'),('Effacer le compte annule-t-il la facture passée ?','Non. L’aide officielle distingue la suppression, qui arrête la reconduction, du paiement correspondant à la période déjà souscrite.')],sources=['resiliation','suppression']),
 dict(slug='wyylde-fiable',cluster='Confiance & sécurité',title='Wyylde est-il fiable ? Sécurité, modération et limites',desc='Wyylde fiable ou arnaque ? Analyse des CGU, avis publics, risques courants et méthodes de vérification.',question='Wyylde est-il une arnaque ?',answer='Wyylde est un service de rencontres pour adultes exploité par une société identifiée et doté de CGU publiques. Cela n’exclut pas les comportements frauduleux d’utilisateurs : distinguez la légitimité du service de la fiabilité d’un profil, d’un message ou d’une proposition de rencontre.',sections=[('Plateforme identifiable, profils à examiner','La présence d’un éditeur français et de conditions publiées est un point vérifiable. Elle ne permet toutefois pas de garantir que chaque contact est authentique. Les plateformes de rencontres rassemblent des personnes aux intentions diverses ; il faut rester attentif à la cohérence d’un profil sur la durée.'),('Les thèmes qui reviennent dans les avis','Les commentaires publics expriment à la fois des appréciations positives sur les échanges et des critiques sur les coûts, les évolutions du site ou les faux profils présumés. Ces témoignages peuvent orienter les questions à poser, mais ils ne constituent pas une statistique représentative du taux de réussite.'),('Signaux d’alerte concrets','Méfiez-vous des demandes de paiement privé, des liens inhabituels, d’un transfert immédiat vers un canal externe ou de pressions pour envoyer des documents personnels. Un profil attrayant et une photo de qualité ne remplacent pas la prudence.'),('Notre grille de sécurité','Privilégiez la confidentialité, utilisez les mécanismes de blocage ou de signalement, gardez les premiers échanges sur la plateforme lorsque c’est possible et choisissez un lieu public adapté en cas de rendez-vous réel. Aucun de ces réflexes n’apporte une garantie absolue, mais ils réduisent l’exposition aux risques.')],faq=[('Wyylde comporte-t-il de faux profils ?','Des internautes en signalent dans leurs avis, mais il n’existe pas de taux indépendant vérifié dans les sources mobilisées.'),('Wyylde rembourse-t-il systématiquement ?','Le remboursement dépend des conditions applicables et de la situation particulière ; ne partez pas du principe qu’il sera automatique.'),('Comment signaler un profil suspect ?','Utilisez les fonctions de signalement prévues par le service et conservez, si nécessaire, des preuves proportionnées sans republier d’informations privées.')],sources=['cgu','avis']),
 dict(slug='wyylde-faux-profils',cluster='Confiance & sécurité',title='Faux profils sur Wyylde : les repérer sans paranoïa',desc='Reconnaître les signaux de faux profils sur Wyylde, utiliser les signalements et protéger ses données.',question='Comment reconnaître un faux profil sur Wyylde ?',answer='Un compte peut être suspect s’il demande rapidement de l’argent, insiste pour quitter la plateforme, présente des informations contradictoires ou exerce une pression. Aucun indice isolé ne prouve une fraude : cherchez plusieurs signaux concordants et utilisez le signalement intégré si nécessaire.',sections=[('Ce qu’un profil ne prouve pas','Une belle photo, un profil détaillé ou une activité régulière ne garantissent pas l’identité de son propriétaire. À l’inverse, un profil discret ne doit pas être automatiquement qualifié de faux : certains utilisateurs cherchent légitimement à préserver leur confidentialité.'),('Réactions adaptées aux signaux d’alerte','Face à une demande d’argent, de cadeau numérique, de cryptoactif ou de document personnel, interrompez l’échange. Lorsqu’une personne souhaite immédiatement quitter le service, restez prudent et refusez toute pression. N’envoyez aucun justificatif à un simple contact.'),('Vérifier sans harceler','Posez des questions simples et cohérentes sur les attentes et limites, sans exiger d’identité civile ni de photo intrusive. Le respect et le consentement doivent rester réciproques. Une réponse évasive peut inviter à ralentir, pas à accuser publiquement la personne.'),('Quand signaler','En présence d’une tentative manifeste de fraude, d’une usurpation ou de menaces, utilisez l’outil de modération disponible. N’affichez pas de captures identifiantes sur un autre réseau social : un signalement est différent d’une dénonciation publique.')],faq=[('Peut-on chiffrer les faux profils Wyylde ?','Non, pas à partir d’avis isolés. Un taux chiffré exige une méthode d’échantillonnage et une vérification indépendante.'),('Un profil de couple peut-il être faux ?','Comme n’importe quel statut, il peut être usurpé. Les informations et la cohérence des échanges comptent davantage que l’étiquette affichée.'),('Que faire si l’on m’a demandé de l’argent ?','Ne payez pas, arrêtez l’échange, conservez les éléments utiles et signalez le compte au service.')],sources=['cgu','avis']),
 dict(slug='wyylde-couple',cluster='Profils & expérience',title='Wyylde en couple : compte partagé, prix et discrétion',desc='Guide pour couples sur Wyylde : compte de couple, tarif Gold identique, confidentialité et communication.',question='Comment fonctionne Wyylde pour un couple ?',answer='Les conditions Wyylde prévoient des comptes de couple. Le tarif Gold est le même que pour les autres statuts en France. Avant de publier, discutez ensemble des photos, des limites, des messages et des informations personnelles visibles : un compte de couple ne dispense pas d’un accord mutuel.',sections=[('Un compte de couple n’efface pas les limites individuelles','Le premier point à clarifier est ce que chacun accepte de montrer, de lire et de proposer. Fixer ces règles avant l’inscription évite qu’une conversation engage involontairement l’autre membre du couple. Prenez régulièrement le temps de les réviser.'),('Un tarif identique pour tous','L’aide officielle publiée le 15 avril 2026 précise qu’il n’existe pas de tarif préférentiel Gold pour les couples. Les prix des trois durées sont les mêmes, avec paiement d’avance pour les formules longues. Comparez le coût total à l’usage réellement envisagé.'),('Créer un profil lisible','Expliquez sobrement les attentes partagées, les disponibilités et les règles de communication. Inutile de multiplier les détails privés. Une description claire aide à écarter plus vite les échanges incompatibles, sans promettre davantage de rencontres.'),('Échanges et confidentialité','Respectez la confidentialité de chacun et vérifiez les réglages des photos. Le consentement à afficher une image doit pouvoir être retiré. En cas de désaccord, il est préférable de suspendre l’usage plutôt que de poursuivre une conversation sous un accord supposé.')],faq=[('Wyylde est-il gratuit pour les couples ?','Non pour Gold : les tarifs officiels ne prévoient pas de réduction systématique pour les couples.'),('Faut-il publier des photos du couple ?','Ce n’est pas une nécessité universelle. Décidez ensemble du niveau de visibilité accepté et vérifiez les réglages disponibles.'),('Un couple peut-il commencer sans payer ?','Il peut s’inscrire gratuitement et examiner les rubriques accessibles, avant de décider d’un Gold.')],sources=['cgu','tarifs']),
 dict(slug='wyylde-homme-seul',cluster='Profils & expérience',title='Wyylde pour homme seul : attentes réalistes et conseils',desc='Wyylde homme seul : fonctionnement, tarif, profil, limites et bonnes pratiques sans promesse de rencontres.',question='Wyylde fonctionne-t-il pour un homme seul ?',answer='Wyylde accepte les utilisateurs majeurs seuls, mais aucun abonnement ne garantit de réponse ni de rencontre. Pour évaluer le service en tant qu’homme seul, vérifiez la pertinence des profils autour de vous, soignez la présentation de votre profil et évitez d’acheter une longue formule sans éléments concrets.',sections=[('Aucun résultat ne peut être garanti','La présence d’un grand nombre d’inscrits ne permet pas de prévoir la qualité des contacts pour un profil précis. Les critères géographiques, les attentes et la réciprocité jouent un rôle majeur. Les comparateurs promettant un taux de réussite certain doivent être abordés avec prudence.'),('Une présentation qui respecte les autres','Une description courte et claire vaut mieux qu’un inventaire d’exigences. Montrez vos centres d’intérêt et ce que vous recherchez, tout en respectant la liberté de réponse. Évitez les messages envoyés en masse et les sollicitations répétées.'),('Le prix reste le même','Tous les statuts sont soumis aux mêmes prix Gold publiés en France. Si vous hésitez, comparez la formule courte à l’usage réellement prévu. La qualité d’un échange n’est pas proportionnelle au prix de l’abonnement.'),('La bonne manière de mesurer l’intérêt','Définissez vos critères avant de payer : présence de profils compatibles, clarté des fonctionnalités, satisfaction par rapport à la confidentialité et coût. Un test honnête doit inclure un résultat éventuellement défavorable, pas seulement des promesses marketing.')],faq=[('Les hommes seuls paient-ils plus cher sur Wyylde ?','Le centre d’aide officiel indique les mêmes prix Gold pour tous les statuts.'),('Quel est le meilleur premier message ?','Un message personnalisé, courtois et court qui montre avoir lu les attentes affichées.'),('Peut-on se faire rembourser faute de rencontre ?','L’absence de rencontre ne constitue pas en soi une garantie de remboursement annoncée dans les sources citées.')],sources=['tarifs','cgu']),
 dict(slug='wyylde-femme-seule',cluster='Profils & expérience',title='Wyylde femme seule : gratuité, confidentialité et sécurité',desc='Femme seule sur Wyylde : prix Gold, précautions, choix des échanges et paramètres de confidentialité.',question='Wyylde est-il gratuit pour une femme seule ?',answer='L’inscription est gratuite, mais le centre d’aide officiel indique que les femmes seules doivent également souscrire Gold pour utiliser les fonctions payantes. Les prix français publiés au 15 avril 2026 sont identiques à ceux des autres statuts.',sections=[('Mettre fin à un mythe tarifaire','Beaucoup d’anciens comparatifs de rencontres appliquent une gratuité automatique aux comptes féminins. Ce n’est pas ce qu’annonce l’aide officielle de Wyylde pour Gold. Les tarifs doivent être vérifiés directement au moment de la souscription.'),('Définir ses limites dès le départ','Un profil clair sur vos préférences de communication peut réduire les sollicitations inadéquates. Vous n’avez pas à répondre à chaque message. Bloquer ou signaler une interaction insistante fait partie des choix légitimes sur une plateforme de rencontre.'),('Protéger ses informations','Évitez les photos permettant d’identifier votre domicile, votre lieu de travail ou votre entourage. Gardez une adresse e-mail dédiée si cela correspond à votre organisation personnelle. Ne transmettez jamais vos documents d’identité à un simple interlocuteur.'),('Évaluer avant de payer','L’usage des fonctionnalités gratuites et la lecture des CGU permettent déjà de vérifier si l’environnement semble adapté. Le paiement ne corrige pas automatiquement des échanges désagréables ou une faible activité autour de votre ville.')],faq=[('Wyylde applique-t-il une réduction femme ?','Le centre d’aide ne prévoit aucune réduction Gold liée au genre ou au statut femme seule.'),('Est-il possible de masquer son identité ?','Le choix d’un pseudonyme et de photos non identifiantes réduit l’exposition, mais aucune méthode ne garantit l’anonymat absolu.'),('Peut-on signaler des messages insistants ?','Oui, utilisez les outils de blocage et de signalement proposés par le service.')],sources=['tarifs','cgu']),
 dict(slug='wyylde-debutant',cluster='Profils & expérience',title='Wyylde débutant : mode d’emploi sans mauvaises surprises',desc='Débuter sur Wyylde : inscription, profil, attentes, abonnement et bonnes pratiques de sécurité.',question='Comment débuter sur Wyylde ?',answer='Pour débuter sur Wyylde, créez d’abord un profil discret et sincère, consultez les rubriques gratuites, vérifiez les règles de confidentialité, puis comparez le prix de Gold à vos besoins. Respectez les limites exprimées par vos interlocuteurs et ne communiquez jamais de données personnelles sensibles sous pression.',sections=[('La première étape n’est pas de payer','Prenez quelques minutes pour explorer le fonctionnement général et lire les règles. Les services gratuits suffisent à comprendre une partie du cadre communautaire. Établissez votre objectif et le type d’échange souhaité avant toute souscription.'),('Un profil utile, pas un dossier personnel','Préférez un texte simple : qui vous êtes, ce que vous cherchez, ce que vous ne cherchez pas et votre manière de communiquer. Un pseudonyme et une photo prudente peuvent suffire pour commencer. Les informations de domicile ou d’employeur n’ont pas leur place sur un profil public.'),('La logique de consentement','Une réponse tardive, un refus ou un changement d’avis doivent être respectés sans insister. Les rencontres entre adultes exigent une communication claire. L’abonnement payant n’accorde aucun droit particulier sur les autres membres.'),('Connaître sa porte de sortie','Vérifiez le renouvellement automatique avant validation de Gold et retenez où trouver les paramètres d’abonnement. Distinguez clairement désactivation du renouvellement et suppression définitive du compte.')],faq=[('Que faire avant son premier paiement ?','Comparer les fonctions accessibles, lire le total facturé, vérifier le renouvellement et mesurer son intérêt réel pour le service.'),('Wyylde est-il réservé aux personnes majeures ?','Oui, les conditions d’utilisation indiquent une plateforme exclusivement réservée aux adultes.'),('Faut-il acheter un an pour commencer ?','Non. Un engagement long peut coûter moins au mois, mais augmente la somme payée sans certitude sur l’utilité future.')],sources=['cgu','tarifs','resiliation']),
 dict(slug='wyylde-application',cluster='Fonctionnement',title='Wyylde sur mobile : application ou site web ?',desc='Utiliser Wyylde sur smartphone : version mobile, confidentialité, notifications et suppression du compte.',question='Peut-on utiliser Wyylde sur smartphone ?',answer='Oui, Wyylde propose une expérience accessible depuis un navigateur mobile et son centre d’aide documente des opérations propres à la version mobile, notamment la suppression du compte. Les disponibilités d’applications dans les boutiques varient : vérifiez uniquement les canaux officiels.',sections=[('Un site utilisable sur petit écran','Pour un usage mobile, privilégiez un navigateur à jour et une connexion sécurisée. Vérifiez les options de confidentialité, les notifications et le comportement de la déconnexion, surtout si le téléphone est partagé.'),('Attention aux fausses applications','Évitez les fichiers APK ou les liens d’installation reçus par message. Si une application officielle est disponible sur votre appareil, utilisez un lien depuis le site Wyylde ou la boutique officielle pour éviter les copies trompeuses.'),('Gérer son abonnement depuis le mobile','Repérez la rubrique Paramètres puis Abonnement depuis votre interface et confirmez l’état de la reconduction automatique. Ne supposez pas qu’effacer un raccourci ou se déconnecter annule l’abonnement.'),('Effacer le compte sur mobile','Le centre d’aide détaille la séquence : menu du compte, Paramètres, Sécurité, puis Supprimer mon compte. Cette action est différente de la simple déconnexion ; vérifiez les conséquences avant confirmation.')],faq=[('Wyylde fonctionne-t-il sans application ?','Oui, le site peut être consulté sur navigateur mobile.'),('Supprimer une application stoppe-t-il Gold ?','Non. Il faut désactiver le renouvellement depuis les paramètres de compte selon la procédure officielle.'),('Comment supprimer son compte depuis son téléphone ?','Le centre d’aide indique menu du compte → Paramètres → Sécurité → Supprimer mon compte.')],sources=['suppressionmobile','resiliation']),
 dict(slug='wyylde-inscription',cluster='Fonctionnement',title='Inscription Wyylde : créer un compte et comprendre Gold',desc='Comment s’inscrire sur Wyylde, quel accès est gratuit, quels détails protéger et quand Gold devient nécessaire.',question='Comment s’inscrire à Wyylde ?',answer='L’inscription Wyylde est gratuite pour les personnes majeures. Vous pouvez commencer par créer votre profil, consulter certains contenus accessibles et régler vos paramètres. Les interactions complètes et certains médias nécessitent ensuite un abonnement Gold, selon les CGU officielles.',sections=[('Avant de commencer','Choisissez un pseudonyme indépendant de vos identifiants publics, une adresse électronique que vous contrôlez et un mot de passe unique. Lisez les CGU ainsi que les informations de confidentialité ; n’incluez pas de données de contact dans le profil destiné aux autres membres.'),('Après la création du profil','Examinez les catégories et les paramètres du site avant de publier des photographies. Vérifiez la visibilité des contenus et évitez de supposer qu’une information peut être retirée des captures déjà effectuées par d’autres utilisateurs.'),('Quand devient-on payant ?','La création du compte ne déclenche pas automatiquement une formule Gold. La souscription est une démarche distincte. Vérifiez le montant total, la durée et la reconduction affichés à l’étape de paiement.'),('Quels droits après paiement ?','Gold ouvre les fonctionnalités payantes définies par le service, mais ne garantit ni rencontres ni réponse. Un abonnement n’impose aucune obligation aux autres utilisateurs.')],faq=[('Wyylde demande-t-il un abonnement dès l’inscription ?','Non, l’inscription est annoncée comme gratuite ; Gold concerne des fonctionnalités additionnelles.'),('Peut-on créer un compte couple ?','Les CGU prévoient les comptes de couple.'),('L’inscription assure-t-elle une rencontre ?','Non. Un service d’échanges ne peut garantir la réponse ou le consentement d’une autre personne.')],sources=['cgu','tarifs']),
 dict(slug='wyylde-supprimer-compte',cluster='Prix & abonnement',title='Supprimer son compte Wyylde : étapes et précautions',desc='Suppression du compte Wyylde : procédure officielle, différence avec la résiliation et données personnelles.',question='Comment supprimer définitivement un compte Wyylde ?',answer='Connectez-vous à Wyylde, ouvrez Paramètres → Sécurité → Supprimer mon compte et confirmez la demande selon les étapes proposées. Si vous n’accédez plus à votre compte, le centre d’aide fournit une procédure via l’assistance. La suppression arrête la reconduction, mais ne rembourse pas automatiquement la période en cours.',sections=[('La procédure depuis le compte','La rubrique Sécurité permet d’initier l’effacement du compte. Un contrôle de l’identité du titulaire peut être demandé pour éviter les suppressions non autorisées. Vérifiez toutes les informations affichées avant la confirmation définitive.'),('Si vous ne pouvez plus vous connecter','Le centre d’aide indique un contact par l’assistance officielle. Évitez de communiquer publiquement votre pseudo, vos justificatifs ou vos détails de paiement ; utilisez uniquement les canaux sécurisés prévus à cet effet.'),('Abonnement et compte : bien distinguer','La suppression met fin au renouvellement automatique selon l’aide de Wyylde, mais l’abonnement déjà payé ne s’arrête pas pour autant sur le plan financier. Si vous souhaitez uniquement empêcher le prochain paiement, la désactivation de la reconduction est généralement l’étape pertinente.'),('Conservation des données : information à vérifier','Attention : deux pages officielles de l’aide Wyylde donnent des délais de conservation différents après suppression. Plutôt que de présenter un délai comme certain, consultez la politique de confidentialité en vigueur ou contactez le DPO du service pour savoir quelles données sont conservées et à quel titre.')],faq=[('Peut-on récupérer le même pseudonyme ?','Selon l’aide, un pseudonyme supprimé peut redevenir disponible et être pris par un autre membre.'),('Supprimer le compte annule-t-il une année déjà payée ?','La suppression coupe la reconduction, mais n’annule pas automatiquement la période souscrite.'),('Combien de temps les données sont-elles gardées ?','La documentation officielle consultée n’est pas cohérente sur ce délai. Consultez la politique à jour et le DPO pour une réponse opposable à votre situation.')],sources=['suppression','donnees','resiliation']),
 dict(slug='wyylde-avis-trustpilot',cluster='Enquête & avis',title='Avis Wyylde Trustpilot : comment lire les témoignages ?',desc='Analyse prudente des avis Trustpilot Wyylde : plaintes, satisfactions, biais de sélection et vérifications utiles.',question='Que disent les avis Wyylde sur Trustpilot ?',answer='Les avis Wyylde sur Trustpilot regroupent des témoignages favorables et défavorables. Certains utilisateurs apprécient les fonctionnalités et les rencontres, tandis que d’autres évoquent le prix, les évolutions de l’offre ou des profils suspects. Ces récits ne donnent pas un taux de réussite mesurable pour tous les membres.',sections=[('Ce qu’un avis raconte vraiment','Un témoignage décrit le vécu de son auteur à une date donnée, pas nécessairement les conditions actuelles du service. La ville, le type de compte, les attentes et les mises à jour de l’interface peuvent modifier fortement l’expérience.'),('Les raisons possibles d’un désaccord','Une personne peut apprécier le réseau social, tandis qu’une autre regrette l’absence de réponses à ses messages. Ces constats ne sont pas contradictoires : les objectifs et les comportements des autres membres comptent davantage qu’un simple score moyen.'),('Repérer les avis pertinents','Privilégiez les témoignages datés, descriptifs et comparables à votre situation. Méfiez-vous des avis extrêmement vagues et des récits qui promettent des rencontres garanties. Consultez également les réponses publiques de l’entreprise lorsqu’elles existent.'),('Notre protocole anti-faux-avis','Nous n’inventons aucune expérience personnelle, aucune statistique de succès, ni aucune note éditoriale chiffrée. Nous mettons en regard les informations vérifiables avec les retours publics, sans faire passer ces derniers pour un échantillon scientifique.')],faq=[('Trustpilot permet-il de savoir si Wyylde fonctionne ?','Non : les avis aident à identifier des problèmes récurrents à vérifier, mais ne prédisent pas votre expérience individuelle.'),('Faut-il croire les avis 5 étoiles ?','Il faut les lire avec les mêmes critères que les critiques négatives : date, contexte, détails et éventuelles incohérences.'),('La note Trustpilot est-elle permanente ?','Non, elle change au fil des évaluations. Consultez la page d’origine pour connaître la note au moment de votre visite.')],sources=['avis','cgu']),
 dict(slug='wyylde-alternatives',cluster='Comparatifs',title='Alternative à Wyylde : les 7 critères pour comparer',desc='Chercher une alternative à Wyylde sans classement artificiel : prix, sécurité, audience, discrétion et désabonnement.',question='Quelle alternative à Wyylde choisir ?',answer='Il n’existe pas d’alternative universellement meilleure que Wyylde. Comparez les plateformes selon la présence de profils correspondant à vos attentes, l’activité dans votre zone, le coût total, les contrôles de confidentialité, la modération, les conditions d’abonnement et la facilité de résiliation.',sections=[('Commencer par l’usage, pas par le nom','Si vous cherchez surtout des échanges communautaires, comparez les fonctionnalités de groupe et de messagerie. Si vous privilégiez les rencontres près de chez vous, la présence réelle de profils locaux compatibles devient un critère central.'),('Le coût total, pas le prix d’appel','Une plateforme moins chère n’a aucun intérêt si elle ne propose pas les fonctions utiles. Comparez les durées, les restrictions de messagerie, les options payantes et le mode de reconduction, en utilisant les informations officielles des services.'),('Protéger ses données partout','Évaluez la facilité avec laquelle vous pouvez modifier la visibilité de vos photos, supprimer un compte et joindre l’assistance. Les garanties marketing de « sécurité totale » n’existent pas : la présence d’une politique lisible et de voies de signalement constitue un meilleur indicateur.'),('Éviter les podiums fabriqués','Un tableau attribuant une note de 9,8/10 sans méthode publiée n’est pas une preuve. Notre grille doit pouvoir mener à une conclusion défavorable pour le partenaire commercial éventuel. Le conseil utile est celui qui expose ses critères et ses limites.')],faq=[('Wyylde est-il le meilleur site libertin ?','Aucune plateforme ne convient à tous. Le service le plus utile dépend des objectifs, de la localisation et des préférences de confidentialité.'),('Comparer uniquement les abonnements suffit-il ?','Non. Il faut aussi tenir compte des fonctionnalités, de la modération et de l’activité locale.'),('Les liens partenaires influencent-ils les classements ?','Ils ne devraient pas. Notre guide n’attribue pas de classements chiffrés invérifiables et signale toute éventuelle relation commerciale.')],sources=['tarifs','cgu']),
 dict(slug='wyylde-confidentialite',cluster='Confiance & sécurité',title='Wyylde et confidentialité : photos, identité et données',desc='Guide de confidentialité Wyylde : pseudonyme, photos, géolocalisation, données et suppression du compte.',question='Comment rester discret sur Wyylde ?',answer='Pour limiter votre exposition sur Wyylde, choisissez un pseudonyme distinct de vos réseaux publics, évitez les photos identifiantes, vérifiez leurs paramètres de visibilité et ne partagez ni adresse ni documents privés avec des inconnus. La discrétion diminue certains risques, mais ne garantit pas l’anonymat.',sections=[('Le risque du recoupement','Une photo déjà publiée ailleurs peut permettre d’identifier une personne par recherche visuelle. Les arrière-plans révèlent parfois des adresses, des plaques ou des lieux de travail. Vérifiez chaque image avant de la rendre visible.'),('Distinguer privé et invisible','Un paramètre de visibilité peut limiter certains accès, sans empêcher une personne autorisée de mémoriser ou de copier une information. Ne publiez jamais un élément dont la diffusion hors de votre contrôle aurait des conséquences importantes.'),('Sécuriser les échanges','Gardez les premières discussions sur la plateforme lorsque cela convient. Ne transmettez pas de pièce d’identité, de mot de passe ou de code de connexion à un contact. Méfiez-vous des fausses demandes de validation envoyées en message privé.'),('Suppression et RGPD','Le centre d’aide décrit une procédure de suppression du compte et une information distincte sur la conservation des données. Ces deux pages ne concordent pas pleinement sur les délais : vérifiez la politique officielle en vigueur et interrogez le DPO si nécessaire.')],faq=[('Peut-on être totalement anonyme sur Wyylde ?','Aucune plateforme relationnelle ne peut garantir l’anonymat absolu. La réduction des informations partagées reste une précaution utile.'),('Faut-il envoyer une carte d’identité à un membre ?','Non. N’envoyez jamais un justificatif d’identité à un simple contact sur la plateforme.'),('La suppression efface-t-elle instantanément toutes les données ?','La documentation officielle indique des modalités de conservation ; deux fiches présentent des délais contradictoires. Vérifiez directement auprès du service.')],sources=['cgu','donnees','suppression']),
 dict(slug='wyylde-soirees',cluster='Fonctionnement',title='Soirées Wyylde : clubs, événements et changements',desc='Événements Wyylde : ce qui peut être consulté, prudence lors des rencontres et évolution des soirées privées.',question='Comment trouver des événements sur Wyylde ?',answer='Les CGU Wyylde mentionnent la consultation de certains événements et pages parmi les services accessibles sans abonnement Gold. Les formats d’événements et les possibilités d’organisation peuvent évoluer. Vérifiez toujours l’annonce officielle, le lieu, le cadre et les conditions d’accès avant de vous déplacer.',sections=[('Un agenda qui peut évoluer','Des avis récents font état de changements concernant les soirées privées et l’organisation entre membres. Ces témoignages décrivent un état à une date donnée. Pour connaître les formats réellement proposés aujourd’hui, fiez-vous d’abord aux rubriques officielles de la plateforme.'),('Lire les informations utiles','Avant de vous déplacer, vérifiez la date, le lieu, le prix d’entrée s’il existe et l’identité de l’organisateur lorsqu’elle est affichée. Une publication en ligne n’est pas une réservation confirmée ni une garantie de sécurité.'),('Consentement et limites','En présentiel comme en ligne, chaque personne doit pouvoir accepter ou refuser une interaction sans pression. Un événement n’entraîne aucune obligation de contact. Respectez les règles de l’établissement et celles des participants.'),('Garder une trace raisonnable','Si un paiement est demandé pour un événement, privilégiez le canal officiel de réservation et conservez le reçu. Évitez les transferts d’argent à des inconnus sous prétexte d’une place réservée.')],faq=[('Les soirées Wyylde sont-elles toujours organisées par les membres ?','La disponibilité de certains formats privés a évolué selon des réponses publiques de Wyylde en 2026 ; vérifiez les annonces sur la plateforme.'),('Faut-il payer Gold pour voir les événements ?','Les CGU mentionnent la consultation de certains événements parmi les services gratuits ; d’autres interactions ou contenus peuvent être réservés à Gold.'),('Un événement garantit-il une rencontre ?','Non. Chaque participant reste libre de ses échanges et de ses décisions.')],sources=['cgu','avis']),
 dict(slug='wyylde-parrainage',cluster='Prix & abonnement',title='Code parrainage Wyylde : un mois offert, sous conditions',desc='Parrainage Wyylde : qui peut en profiter, comment fonctionne le mois offert et quels pièges éviter.',question='Existe-t-il un code de parrainage Wyylde ?',answer='Oui. L’aide officielle Wyylde décrit un parrainage donnant un mois d’abonnement offert au parrain et au filleul, sous conditions. Le filleul doit notamment être majeur, créer un premier compte depuis le lien de parrainage et souscrire un premier abonnement Gold valide.',sections=[('Le mécanisme annoncé','Le parrain partage son lien personnel depuis les paramètres. Le nouvel utilisateur s’inscrit depuis ce lien puis souscrit Gold selon les conditions décrites. Les trente jours sont alors ajoutés aux deux abonnements si le parcours est intégralement validé.'),('Les principales limites','La documentation précise que l’offre ne peut pas forcément être combinée à un code promotionnel et qu’une inscription ne passant pas par le bon lien peut empêcher le suivi du parrainage. Il ne faut donc pas annoncer « Gold gratuit sans payer » : un premier abonnement payant est requis.'),('Ne pas publier de codes trompeurs','Les pages qui affichent des « codes exclusifs 100 % gratuits » sans source ni date peuvent induire en erreur. Notre guide ne diffuse pas de lien de parrainage inventé et ne promet pas de bénéficier de promotions non vérifiées.'),('Vérifier votre éligibilité','Consultez les conditions sur Wyylde au moment de souscrire, notamment votre statut de nouveau membre, l’offre active, les restrictions de cumul et le montant effectivement facturé.')],faq=[('Le parrainage permet-il d’avoir Gold gratuitement sans payer ?','Non : le centre d’aide indique une souscription initiale à une formule Gold comme condition.'),('Le mois offert est-il automatique ?','Selon l’aide, il est crédité quand toutes les conditions sont satisfaites et le suivi du lien fonctionne.'),('Peut-on cumuler parrainage et code promo ?','La documentation signale qu’un code promotionnel peut empêcher l’obtention du bénéfice du parrainage.')],sources=['parrainage','tarifs']),
 dict(slug='wyylde-vs-libertic',cluster='Comparatifs',title='Wyylde ou Libertic : comment choisir sans biais ?',desc='Wyylde vs Libertic : critères pratiques pour comparer communauté, tarifs, expérience et confidentialité.',question='Wyylde ou Libertic : lequel choisir ?',answer='Le choix entre Wyylde et Libertic dépend de votre objectif. Comparez leur activité locale, leurs outils d’échange, les coûts réellement affichés, la facilité de désabonnement et le contrôle des données. Sans test simultané et indépendant, il serait trompeur de promettre un gagnant valable pour tous.',sections=[('Même usage, critères comparables','Commencez par noter les fonctions nécessaires : recherche, messagerie, profils de couple, animation communautaire et accès mobile. Vérifiez directement ce qui est inclus dans les offres actuelles de chaque service.'),('Un prix ne suffit pas','Wyylde affiche officiellement Gold à 22,90 € pour un mois, 44,90 € pour trois mois et 99,90 € pour un an, selon son aide d’avril 2026. Sans vérification actualisée des tarifs Libertic, il serait incorrect de donner un tableau chiffré affirmant qu’il est forcément moins cher.'),('Quel site dispose des profils utiles ?','Une base d’inscrits importante n’indique pas automatiquement une activité forte dans chaque département. Mesurez surtout la présence de comptes compatibles et les fonctionnalités de recherche accessibles avant paiement.'),('Méthode honnête','Faites votre propre grille de comparaison plutôt que de suivre une note de 9,9/10 non justifiée. Évitez de payer deux longues formules avant d’avoir identifié les différences utiles à votre situation.')],faq=[('Wyylde est-il plus cher que Libertic ?','Les tarifs Wyylde sont sourcés ici ; ceux de Libertic doivent être vérifiés à la date de comparaison pour conclure correctement.'),('Quel site est le plus discret ?','Comparez les réglages de confidentialité disponibles au moment de l’inscription et la facilité de retrait des contenus.'),('Faut-il payer les deux pour comparer ?','Non. Commencez par les informations et fonctionnalités gratuites, puis décidez si un test payant est réellement nécessaire.')],sources=['tarifs','cgu']),
]

CSS='''
:root{color-scheme:light;--ink:#172529;--muted:#52666a;--paper:#f7f5ef;--white:#fffefb;--mist:#e8f1ec;--line:#dbe3df;--a:#136454;--a2:#0c483d;--warm:#e9bb77;--radius:20px;font-family:system-ui,-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--paper);color:var(--ink);font-size:16px;line-height:1.72}a{color:var(--a2);text-decoration-thickness:1px;text-underline-offset:3px}a:hover{color:#a35221}a:focus-visible,button:focus-visible,summary:focus-visible,input:focus-visible{outline:3px solid #d49731;outline-offset:3px}p{margin:0 0 1.2rem}h1,h2,h3{font-family:Georgia,'Times New Roman',serif;line-height:1.16;letter-spacing:-.025em}h1{font-size:clamp(2.4rem,6vw,5rem);max-width:920px;margin:.35em 0}h2{font-size:clamp(1.6rem,3.2vw,2.65rem);margin:2.2rem 0 1rem}h3{font-size:1.45rem;margin:1.7rem 0 .5rem}strong{color:var(--ink)}small{color:var(--muted)}.wrap{max-width:1160px;padding:0 24px;margin:auto}.top{border-bottom:1px solid #d7e6dc;background:var(--white);position:sticky;top:0;z-index:10}.top .bar{height:76px;display:flex;gap:2rem;align-items:center;justify-content:space-between}.logo{text-decoration:none;color:var(--ink);font-weight:800;letter-spacing:-.06em;font-size:1.28rem;line-height:1}.logo .g{color:var(--a)}.logo small{font-weight:500;font-size:.65rem;letter-spacing:.12em;display:block;margin-top:6px}.nav{display:flex;gap:20px;align-items:center;font-size:.86rem;font-weight:650}.nav a{text-decoration:none}.tag{display:inline-flex;align-items:center;gap:7px;letter-spacing:.12em;text-transform:uppercase;font-size:.72rem;font-weight:750;color:var(--a2)}.tag:before{content:'✦';color:var(--a)}.hero{background:radial-gradient(circle at 87% 25%,#bddbd1 0,transparent 25%),radial-gradient(circle at 73% 70%,#e4efdf 0,transparent 34%),linear-gradient(125deg,#eff3e9 0,#faf8ef 70%);position:relative;overflow:hidden;padding:92px 0 75px}.hero:after{content:'W';position:absolute;right:-25px;bottom:-170px;font:400 600px Georgia,serif;color:#0a624b;opacity:.045;pointer-events:none}.hero .lead{font-size:clamp(1.1rem,2vw,1.37rem);max-width:720px;color:#344e4d;line-height:1.65}.eyebrow{display:flex;gap:10px;font-size:.83rem;color:var(--a2);font-weight:750;letter-spacing:.12em;text-transform:uppercase}.hero-actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:26px}.btn{border-radius:100px;text-decoration:none;font-weight:760;padding:12px 22px;display:inline-flex;gap:9px;align-items:center;border:1px solid var(--a2);font-size:.93rem}.btn.main{background:var(--a2);color:white}.btn.soft{background:transparent}.meta{color:#56736b;font-size:.78rem;margin-top:30px}.topline{display:flex;justify-content:space-between;align-items:center;gap:15px;flex-wrap:wrap}.trust{display:flex;gap:13px;flex-wrap:wrap;margin-top:32px}.trust span{border:1px solid #c9dbcd;background:#fcfffac9;border-radius:100px;padding:6px 12px;font-size:.74rem;color:#31534a}.section-intro{max-width:740px;color:var(--muted);font-size:1.04rem}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.card{background:var(--white);padding:27px;border-radius:18px;border:1px solid var(--line);box-shadow:0 10px 28px #1d5e3b09;display:flex;flex-direction:column}.card .k{font-size:.7rem;text-transform:uppercase;letter-spacing:.13em;color:#678078;font-weight:800}.card h3{margin:.7rem 0 .65rem}.card a.stretched{font-weight:800;text-decoration:none;margin-top:auto;padding-top:6px}.card p{color:var(--muted);font-size:.91rem}.section{padding:56px 0}.pill{display:inline-block;background:var(--mist);border-radius:100px;color:var(--a2);font-size:.75rem;font-weight:750;padding:5px 11px}.strip{padding:27px 35px;border-radius:20px;background:var(--a2);color:white;display:flex;gap:25px;align-items:center;justify-content:space-between;margin:20px 0 40px}.strip p{margin:0;color:#d2e7df}.strip h2{color:white;margin:.15rem 0 .45rem;font-size:2rem}.strip a{color:white}.statrow{display:grid;grid-template-columns:repeat(3,1fr);gap:1px;border:1px solid var(--line);background:var(--line);border-radius:20px;overflow:hidden}.statrow>div{padding:22px;background:white}.statrow strong{font-family:Georgia,serif;font-size:2rem;color:var(--a2);display:block}.statrow small{font-size:.78rem}.layout{display:grid;grid-template-columns:minmax(0,1fr) 265px;gap:55px;align-items:start;padding-top:43px}.article{min-width:0}.article h2{margin-top:2.3rem}.article p{font-size:1.03rem;line-height:1.86;color:#324146}.article .answer{background:#edf4ef;border-left:5px solid var(--a);padding:26px 28px;margin:25px 0;border-radius:0 16px 16px 0}.answer h2{font-size:1.45rem;margin:0 0 .6rem}.answer p{margin:0;font-size:1.08rem;color:#203c36;font-weight:510}.crumb{font-size:.81rem;color:var(--muted);padding:23px 0 0}.crumb a{color:var(--muted)}.article section{scroll-margin-top:90px}.aside{position:sticky;top:110px;background:var(--white);border:1px solid var(--line);border-radius:20px;padding:24px}.aside strong{display:block;margin-bottom:9px}.aside a{display:block;padding:9px 0;border-bottom:1px solid #e6ede9;font-size:.84rem;text-decoration:none}.aside a:last-child{border:0}.question{border-bottom:1px solid var(--line);padding:12px 0}.question summary{font-weight:780;cursor:pointer;font-size:1rem}.question p{margin:9px 0;font-size:.95rem}.sources{margin-top:42px;font-size:.84rem;background:white;padding:25px;border-radius:16px;border:1px solid var(--line)}.sources ul{padding-left:20px}.related{background:#e9eee7;padding:40px 0 75px;margin-top:70px}.related .grid{grid-template-columns:repeat(3,1fr)}.footer{background:#112e28;color:#d6e4d9;padding:44px 0;font-size:.87rem}.footer a{color:#d7efe3}.footgrid{display:grid;grid-template-columns:1.5fr 1fr 1fr;gap:40px}.footer p,.footer small{color:#c7d8d1}.footer .logo{color:#fff}.footlinks a{display:block;padding:5px 0}.conclusion{border-top:1px solid var(--line);margin-top:38px;padding-top:15px}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}::selection{background:#d4efd9}
@media(max-width:920px){.grid{grid-template-columns:repeat(2,minmax(0,1fr))}.layout{grid-template-columns:minmax(0,1fr)}.aside{position:static}.hero{padding:62px 0}.nav{gap:10px;font-size:.75rem}}
@media(max-width:640px){.wrap{padding:0 18px}.top .bar{height:70px}.nav a:not(:last-child){display:none}.grid,.related .grid,.footgrid,.statrow{grid-template-columns:1fr}.hero{padding:54px 0 60px}.hero:after{font-size:370px;bottom:-130px}.card{padding:22px}.strip{display:block;padding:25px}.layout{gap:25px;padding-top:26px}.statrow>div{padding:15px 20px}.article .answer{padding:19px}.section{padding:30px 0}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}
'''

def E(x):return html.escape(str(x),quote=True)
def href(slug):return f'/{slug}/'
def card(a):
 return f'<article class="card"><span class="k">{E(a["cluster"])}</span><h3><a href="{href(a["slug"])}">{E(a["title"])}</a></h3><p>{E(a["desc"])}</p><a class="stretched" href="{href(a["slug"])}" aria-label="Lire {E(a["title"])}">Lire le guide ↗</a></article>'
def schema_json(o):return json.dumps(o,ensure_ascii=False).replace('</','<\\/')
def header():return '<header class="top"><div class="wrap bar"><a class="logo" href="/">W<span class="g">.</span> LE GUIDE<small>WYYLDE AVIS · INDÉPENDANT</small></a><nav class="nav" aria-label="Navigation principale"><a href="/wyylde-avis/">Notre avis</a><a href="/wyylde-prix/">Tarifs</a><a href="/wyylde-fiable/">Fiabilité</a><a href="/wyylde-alternatives/">Alternatives</a></nav></div></header>'
def footer():return '<footer class="footer"><div class="wrap footgrid"><div><a class="logo" href="/">W<span class="g">.</span> LE GUIDE</a><p>Guide éditorial indépendant. Aucun faux témoignage, aucune promesse de classement ou de rencontre. Informations réservées aux adultes.</p></div><div><b>Comprendre</b><div class="footlinks"><a href="/wyylde-avis/">Avis Wyylde</a><a href="/wyylde-gratuit/">Gratuit ou payant ?</a><a href="/wyylde-resiliation/">Résilier Gold</a><a href="/wyylde-confidentialite/">Confidentialité</a></div></div><div><b>Transparence</b><p>Sources officielles consultées le 17 octobre 2026. Analyse documentaire, sans achat ou essai personnel revendiqué. Aucun lien d’affiliation activé.</p><small>© 2026 Le Guide W. · Non affilié à Wyylde.</small></div></div></footer>'
def head(title,desc,path,json_data):
 return f'''<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#f7f5ef"><meta name="robots" content="index,follow,max-image-preview:large,max-snippet:-1"><title>{E(title)}</title><meta name="description" content="{E(desc)}"><link rel="canonical" href="{E(BASE_URL+path)}"><meta property="og:type" content="article"><meta property="og:locale" content="fr_FR"><meta property="og:title" content="{E(title)}"><meta property="og:description" content="{E(desc)}"><meta property="og:url" content="{E(BASE_URL+path)}"><link rel="stylesheet" href="/style.css"><script type="application/ld+json">{schema_json(json_data)}</script></head><body><a class="sr-only" href="#contenu">Aller au contenu</a>{header()}'''

def page(a):
 path=href(a['slug']);related=[q for q in ARTICLES if q['slug']!=a['slug'] and (q['cluster']==a['cluster'])][:2];related += [q for q in ARTICLES if q['slug'] not in {a['slug'],*(i['slug'] for i in related)}][:1]
 data=[{'@context':'https://schema.org','@type':'Article','headline':a['title'],'description':a['desc'],'datePublished':DATE,'dateModified':DATE,'inLanguage':'fr-FR','mainEntityOfPage':BASE_URL+path,'author':{'@type':'Organization','name':'Le Guide W — Rédaction indépendante'},'publisher':{'@type':'Organization','name':'Le Guide W'}},{'@context':'https://schema.org','@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'Accueil','item':BASE_URL+'/'},{'@type':'ListItem','position':2,'name':a['title'],'item':BASE_URL+path}]}]
 h=head(a['title']+' | Le Guide W',a['desc'],path,data)
 h+=f'<div class="wrap crumb"><a href="/">Accueil</a> <span aria-hidden="true">/</span> <span>{E(a["cluster"])}</span></div><main id="contenu"><div class="wrap layout"><article class="article"><span class="tag">{E(a["cluster"])} · Mise à jour 17 octobre 2026</span><h1>{E(a["title"])}</h1><p class="section-intro">{E(a["desc"])}</p><div class="answer"><h2>{E(a["question"])}</h2><p>{E(a["answer"])}</p></div>'
 for i,part in enumerate(a['sections']):
  h+=f'<section id="point-{i+1}"><h2>{E(part[0])}</h2>'+''.join(f'<p>{E(p)}</p>' for p in part[1:])+'</section>'
 h+='<section id="questions-frequentes"><h2>Questions fréquentes</h2><p>Réponses synthétiques aux recherches associées, avec des limites explicites quand une donnée n’est pas démontrée.</p>'
 for q,ans in a['faq']:h+=f'<details class="question"><summary>{E(q)}</summary><p>{E(ans)}</p></details>'
 h+='</section><div class="sources"><h3>Sources et méthode</h3><p>Les faits tarifaires et contractuels sont attribués à la documentation officielle. Les avis de clients sont décrits comme des témoignages et non comme des mesures représentatives. Les conditions peuvent changer.</p><ul>'
 for key in a['sources']:
  n,u=SOURCES[key];h+=f'<li><a href="{E(u)}" rel="noopener noreferrer" target="_blank">{E(n)} ↗</a></li>'
 h+='</ul></div><div class="conclusion"><p><strong>À retenir :</strong> '+E(a['answer'])+'</p></div></article><aside class="aside" aria-label="Sommaire de la page"><strong>Dans ce guide</strong>'
 for i,part in enumerate(a['sections']):h+=f'<a href="#point-{i+1}">{E(part[0])}</a>'
 h+='<a href="#questions-frequentes">Questions fréquentes</a><a href="/wyylde-avis/">← Voir l’avis complet</a></aside></div><section class="related"><div class="wrap"><span class="tag">Maillage interne</span><h2>Continuer l’enquête</h2><div class="grid">'+''.join(card(r) for r in related)+'</div></div></section></main>'+footer()+'</body></html>'
 return h

def homepage():
 schema={'@context':'https://schema.org','@type':'WebSite','name':SITE_NAME,'url':BASE_URL+'/','inLanguage':'fr-FR','description':'Guide indépendant sur Wyylde : avis, tarifs, sécurité, fonctionnalités et alternatives.'}
 h=head('Wyylde avis 2026 : prix, fiabilité et guide indépendant','Wyylde avis 2026 : enquête indépendante, prix Gold officiels, résiliation, profils, sécurité et 16 guides pratiques pour choisir sans pression.','/',schema)
 h+='''<main id="contenu"><section class="hero"><div class="wrap"><span class="tag">Le dossier complet · 2026</span><h1>Wyylde avis :<br><em>au-delà des promesses.</em></h1><p class="lead">Prix réels, fonctionnement, profils, confidentialité et résiliation : un guide indépendant qui répond aux questions avant l’abonnement, sans faux témoignages ni classement fabriqué.</p><div class="hero-actions"><a class="btn main" href="/wyylde-avis/">Lire notre avis détaillé →</a><a class="btn soft" href="/wyylde-prix/">Comparer les prix Gold</a></div><div class="trust"><span>✓ Tarifs officiels sourcés</span><span>✓ 16 analyses thématiques</span><span>✓ Réponses claires & rapides</span><span>✓ Indépendant de Wyylde</span></div><div class="meta">Mise à jour : 17 octobre 2026 · Réservé aux personnes majeures</div></div></section><section class="section"><div class="wrap"><span class="tag">L’essentiel, tout de suite</span><h2>Ce qu’il faut savoir avant de payer</h2><p class="section-intro">L’inscription gratuite, l’accès Gold et la résiliation sont trois sujets différents. Nous avons vérifié les tarifs dans le centre d’aide officiel.</p><div class="statrow"><div><strong>22,90 €</strong><small>Gold : 1 mois · tarif publié en France</small></div><div><strong>44,90 €</strong><small>Gold : 3 mois · payé en une fois</small></div><div><strong>99,90 €</strong><small>Gold : 12 mois · payé en une fois</small></div></div><p class="meta">Source : <a href="https://ask.wyylde.com/hc/fr-fr/articles/33917905975442-Les-tarifs-et-les-formules-d-abonnements" target="_blank" rel="noopener noreferrer">Wyylde, tarifs officiels du 15/04/2026 ↗</a>. Conditions et promotions susceptibles d’évoluer.</p><div class="strip"><div><h2>Un abonnement n’est pas une promesse de rencontre.</h2><p>La valeur du service dépend de vos attentes, de votre zone et des interactions réellement disponibles.</p></div><a class="btn soft" href="/wyylde-fiable/">Fiabilité & risques ↗</a></div></div></section>'''
 groups=[('Enquête & avis','Comprendre le service et les témoignages publics'),('Prix & abonnement','Réponses sourcées sur le paiement, le gratuit et l’arrêt de Gold'),('Profils & expérience','Les attentes changent selon le type de profil'),('Confiance & sécurité','La discrétion et les vérifications pratiques'),('Fonctionnement','S’inscrire, utiliser le mobile et découvrir les événements'),('Comparatifs','Choisir avec une grille objective')]
 for name,txt in groups:
  group=[a for a in ARTICLES if a['cluster']==name]
  h+=f'<section class="section"><div class="wrap"><span class="tag">Cocon sémantique</span><h2>{E(name)}</h2><p class="section-intro">{E(txt)}</p><div class="grid">'+''.join(card(a) for a in group)+'</div></div></section>'
 h+='''<section class="section"><div class="wrap"><span class="tag">ASTRA · Ressources déjà créées</span><h2>Nos analyses complémentaires</h2><p class="section-intro">Deux guides existants sont conservés et liés pour approfondir certains thèmes sans modifier leurs URLs.</p><div class="grid"><article class="card"><span class="k">Guide externe de notre réseau</span><h3>Comparatif & alternatives</h3><p>Une grille détaillée pour comparer plusieurs services selon les mêmes critères.</p><a class="stretched" href="https://wyylde-comparatif-alternatives-fuc3vk.v2.appdeploy.ai/" rel="noopener noreferrer">Lire le comparatif ↗</a></article><article class="card"><span class="k">Guide externe de notre réseau</span><h3>Guide Wyylde Sécurité</h3><p>Précautions sur les photos, les échanges et la protection de vos informations.</p><a class="stretched" href="https://guide-wyylde-securite-40u4od.v2.appdeploy.ai/" rel="noopener noreferrer">Lire les conseils de sécurité ↗</a></article><article class="card"><span class="k">Source primaire</span><h3>Conditions générales</h3><p>Vérifier les fonctionnalités accessibles et les règles du service chez l’éditeur.</p><a class="stretched" href="https://app.wyylde.com/fr-fr/policies" target="_blank" rel="noopener noreferrer">Consulter les CGU ↗</a></article></div></div></section></main>'''+footer()+'</body></html>'
 return h

if OUT.exists():shutil.rmtree(OUT)
OUT.mkdir(parents=True)
(OUT/'style.css').write_text(CSS,encoding='utf-8')
(OUT/'index.html').write_text(homepage(),encoding='utf-8')
for a in ARTICLES:
 d=OUT/a['slug'];d.mkdir();(d/'index.html').write_text(page(a),encoding='utf-8')
urls=['/']+[href(a['slug']) for a in ARTICLES]
(OUT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'+''.join(f'<url><loc>{xml_escape(BASE_URL+x)}</loc><lastmod>{DATE}</lastmod></url>\n' for x in urls)+'</urlset>\n',encoding='utf-8')
(OUT/'robots.txt').write_text(f'User-agent: *\nAllow: /\nSitemap: {BASE_URL}/sitemap.xml\n',encoding='utf-8')
(OUT/'404.html').write_text(head('Page introuvable | Le Guide W','Cette page est introuvable.','/404.html',{'@context':'https://schema.org','@type':'WebPage','name':'Page introuvable'})+'<main id="contenu" class="wrap" style="min-height:50vh"><h1>Page introuvable</h1><p>Cette adresse ne correspond à aucun de nos guides.</p><a class="btn main" href="/">Retour à l’accueil</a></main>'+footer()+'</body></html>',encoding='utf-8')
(BASE/'README.md').write_text('''# Wyylde Avis — Le Guide W (17/10/2026)\n\nSite de contenu indépendant, sans WordPress, cookies, traqueurs, JS ni abonnement. 17 URLs HTML pré-rendues : accueil + 16 pages, chacune dotée de titre, description, canonical, OG, JSON-LD Article/Breadcrumb et questions/réponses visibles. Les tarifs proviennent du centre d’aide officiel Wyylde (15/04/2026). Aucune promesse de position Google.\n\n## Construire avec votre vrai domaine\n\n```bash\nSITE_URL=https://votre-domaine.fr python3 build_site.py\n```\n\nPublier le contenu de `dist/` à la racine du domaine (Netlify Drop, Cloudflare Pages, Vercel, etc.). Remplacer `SITE_URL` par la vraie URL AVANT publication : le sitemap et les canoniques doivent correspondre au domaine définitif. Aucune dépense ni clé API requise.\n\n## Vérifier localement\n\n```bash\npython3 -m http.server 8000 -d dist\npython3 audit_site.py\n```\n\nLes prix ou modalités Wyylde peuvent changer ; mettre à jour les articles concernés avant d'affirmer une nouveauté. **Attention : les fiches officielles Wyylde donnent des informations contradictoires sur le délai d’effacement de certaines données.**\n\nAucun programme d’affiliation n’a été configuré : ne pas insérer de code fictif.\n''',encoding='utf-8')
print(json.dumps({'pages':len(urls),'path':str(OUT),'base_url':BASE_URL,'clusters':len(set(a['cluster'] for a in ARTICLES))},ensure_ascii=False))